`,e.jsx(t.li,{children:e.jsx(t.a,{href:"/blog/how-a-four-stroke-engine-works",children:"The 4 Strokes of an Engine: Intake, Compression, Power, Exhaust"})}),`
`,e.jsx(t.li,{children:e.jsx(t.a,{href:"/blog/what-is-engine-knock",children:"What Is Engine Knock? Causes, Sounds, and How to Stop It"})}),`
