`,e.jsxs(t.table,{children:[e.jsx(t.thead,{children:e.jsxs(t.tr,{children:[e.jsx(t.th,{children:"Compression ratio"}),e.jsx(t.th,{children:"Ideal η"}),e.jsx(t.th,{children:"Measured η"})]})}),e.jsxs(t.tbody,{children:[e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"8"}),e.jsx(t.td,{children:"56.5%"}),e.jsx(t.td,{children:"29.9%"})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"10"}),e.jsx(t.td,{children:"60.2%"}),e.jsx(t.td,{children:"33.1%"})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"12"}),e.jsx(t.td,{children:"63.0%"}),e.jsx(t.td,{children:"35.8%"})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:e.jsx(t.strong,{children:"13"})}),e.jsx(t.td,{children:"64.2%"}),e.jsx(t.td,{children:e.jsx(t.strong,{children:"35.9% (peak)"})})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"14"}),e.jsx(t.td,{children:"65.2%"}),e.jsx(t.td,{children:"35.5%"})]})]})]}),`
