`]})]})}function dt(n={}){const{wrapper:t}=n.components||{};return t?e.jsx(t,{...n,children:e.jsx(L,{...n})}):L(n)}const ct=Object.freeze(Object.defineProperty({__proto__:null,default:dt,frontmatter:ce},Symbol.toStringTag,{value:"Module"})),ue={title:"Firing Order Explained: SBC, LS, Ford, Hemi and Diesel Orders",date:"2026-10-05",excerpt:"Firing order is the sequence an engine's cylinders fire in: the SBC, LS, Ford, Hemi, Duramax and Power Stroke orders, cylinder numbering, and what it changes.",readingMinutes:17,author:"Engine Simulator Team",draft:!1,image:"/blog/firing-order.png",imageAlt:"A V8 engine seen from above, distributor at the front, with two spark plug wires glowing as they run to cylinders on opposite banks"};function R(n){const t={a:"a",blockquote:"blockquote",h2:"h2",h3:"h3",img:"img",li:"li",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...n.components};return e.jsxs(e.Fragment,{children:[e.jsx(t.p,{children:"Every multi-cylinder engine fires its cylinders in a fixed sequence, and that sequence is its firing order. A small-block Chevy fires 1-8-4-3-6-5-7-2. A GM LS fires 1-8-7-2-6-5-4-3. A Fox-body 5.0 HO Mustang fires 1-3-7-2-6-5-4-8, a Coyote Mustang 1-5-4-8-6-3-7-2, and an older 302 1-5-4-2-6-3-7-8. You need the number whenever you wire a distributor, replace coil packs or swap a camshaft, and you need to know how that engine's maker numbers its cylinders before the number means anything."}),`
`,e.jsxs(t.p,{children:["This article has the common orders in one table with their sources, explains the numbering, and then answers the question the forums argue about: does firing order change power or sound? We tested it in our simulator by typing four different firing orders into the same V8. You can ",e.jsx(t.a,{href:"/simulator?engine=v8_5L&mod=eyJ2IjoxLCJmaXJpbmdPcmRlciI6WzEsOCw3LDIsNiw1LDQsM119",children:"open that V8 with the LS order"})," and hear it."]}),`
`,e.jsxs(t.blockquote,{children:[`
`,e.jsx(t.p,{children:e.jsx(t.strong,{children:"Key Takeaways"})}),`
`,e.jsxs(t.ul,{children:[`
`,e.jsx(t.li,{children:"Firing order is the sequence in which the cylinders of an engine fire. It is set by the crankshaft and camshaft (and, on older engines, the distributor), and the spark plug wires or coils must follow it."}),`
`,e.jsxs(t.li,{children:["Common V8 orders: small-block and big-block Chevy, older Chrysler and Gen III Hemi ",e.jsx(t.strong,{children:"1-8-4-3-6-5-7-2"}),"; GM LS and LT ",e.jsx(t.strong,{children:"1-8-7-2-6-5-4-3"}),"; Ford 289/302 ",e.jsx(t.strong,{children:"1-5-4-2-6-3-7-8"}),"; Ford 5.0 HO, 351W and 4.6/5.4 modular ",e.jsx(t.strong,{children:"1-3-7-2-6-5-4-8"}),"; Ford Coyote in the Mustang ",e.jsx(t.strong,{children:"1-5-4-8-6-3-7-2"}),"."]}),`
`,e.jsx(t.li,{children:"The same digits mean different cylinders on different makes. GM and Chrysler gasoline V8s put odd cylinders (1-3-5-7) on the driver side; Ford numbers 1-2-3-4 down the passenger side and 5-6-7-8 down the driver side."}),`
`,e.jsxs(t.li,{children:["In our simulator, changing a V8's firing order while keeping the 90° spacing changed its power by ",e.jsx(t.strong,{children:"nothing at all"}),": 297.251 hp for all four orders tested. It did change the rhythm of exhaust pulses down each bank, which the simulator routes to each bank's exhaust sound. The real reasons engineers choose an order (crankshaft vibration, bearing loads, cooling, intake distribution, exhaust pulse interaction) are effects this model does not simulate, so its zero is the order with those effects taken out."]}),`
`,e.jsxs(t.li,{children:["In the simulator, the spacing between firings changes more than the order does. On its V-twin, bunching the two firings from 360° apart to 180° apart raised the crank-speed ripple at idle by ",e.jsx(t.strong,{children:"54%"}),"."]}),`
`]}),`
