`,e.jsxs(t.li,{children:[e.jsx(t.a,{href:"https://en.wikipedia.org/wiki/Torque",children:"Wikipedia: Torque"})," (retrieved 2026-09-22): the 5,252 constant"]}),`
`,e.jsxs(t.li,{children:[e.jsx(t.a,{href:"https://www.intertekinform.com/en-us/standards/sae-j-1349-2011-1020039_saig_sae_sae_2375015/",children:"SAE J1349: Engine Power Test Code, Spark Ignition and Compression Ignition, As Installed Net Power Rating"})," (retrieved 2026-09-22)"]}),`
