`,e.jsxs(t.li,{children:[e.jsx(t.a,{href:"https://media.stellantisnorthamerica.com/newsrelease.do?id=15328",children:"Stellantis: Ram Truck and Cummins Celebrate 25 Years of Diesel Powertrain Leadership"})," (retrieved 2026-09-22): the 1989 160 hp / 400 lb·ft rating"]}),`
`,e.jsxs(t.li,{children:[e.jsx(t.a,{href:"https://en.wikipedia.org/wiki/LS_based_GM_small-block_engine",children:"Wikipedia: LS based GM small-block engine"})," (retrieved 2026-09-22): LS7 505 hp @ 6,300, 470 lb·ft @ 4,800"]}),`
`,e.jsxs(t.li,{children:[e.jsx(t.a,{href:"https://www.grandprixengines.co.uk/Note_108.pdf",children:"Ian Bamsey, Note 108: Cosworth 2006 Type CA"})," (PDF, retrieved 2026-09-22): 755 bhp @ 19,250, 214.4 lb·ft @ 17,000, from Cosworth data"]}),`
`,e.jsxs(t.li,{children:[e.jsx(t.a,{href:"https://www.caranddriver.com/news/a15347872/horsepower-vs-torque-whats-the-difference/",children:"Car and Driver: Horsepower vs. Torque: What's the Difference?"})," (retrieved 2026-09-22)"]}),`
`,e.jsxs(t.li,{children:[e.jsx(t.a,{href:"https://cseweb.ucsd.edu/classes/sp19/cse291-d/Files/CSE291_14_VehicleDynamics.pdf",children:"UC San Diego CSE 291, Vehicle Dynamics lecture notes"})," (PDF, retrieved 2026-09-22): gearbox torque and speed"]}),`
`,e.jsxs(t.li,{children:[e.jsx(t.a,{href:"https://en.wikipedia.org/wiki/Tractive_effort",children:"Wikipedia: Tractive effort"})," (retrieved 2026-09-22)"]}),`
