`,e.jsx(t.p,{children:e.jsx(t.img,{src:"/blog/torque-converter-launch.svg",alt:"Line chart of a measured standing start. Engine speed rises quickly from 826 rpm, eases near 2,300 rpm around half a second in, then climbs steadily with road speed to about 6,650 rpm just past five seconds, where the box changes up. Torque multiplication, on a right-hand axis marked in multiples, starts at 2.10 times at rest and falls smoothly to 1.00 at the 2.4 second coupling point, after which it stays flat."})}),`
`,e.jsxs(t.table,{children:[e.jsx(t.thead,{children:e.jsxs(t.tr,{children:[e.jsx(t.th,{children:"t (s)"}),e.jsx(t.th,{children:"Speed ratio"}),e.jsx(t.th,{children:"Torque ratio"}),e.jsx(t.th,{children:"Engine rpm"}),e.jsx(t.th,{children:"Road speed"})]})}),e.jsxs(t.tbody,{children:[e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"0.0"}),e.jsx(t.td,{children:"0.001"}),e.jsx(t.td,{children:e.jsx(t.strong,{children:"2.098"})}),e.jsx(t.td,{children:"826"}),e.jsx(t.td,{children:"0.0 km/h"})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"0.2"}),e.jsx(t.td,{children:"0.120"}),e.jsx(t.td,{children:"1.945"}),e.jsx(t.td,{children:"1,898"}),e.jsx(t.td,{children:"3.4 km/h"})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"0.5"}),e.jsx(t.td,{children:"0.309"}),e.jsx(t.td,{children:"1.700"}),e.jsx(t.td,{children:"2,280"}),e.jsx(t.td,{children:"10.4 km/h"})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"1.0"}),e.jsx(t.td,{children:"0.568"}),e.jsx(t.td,{children:"1.365"}),e.jsx(t.td,{children:"2,642"}),e.jsx(t.td,{children:"22.1 km/h"})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"2.0"}),e.jsx(t.td,{children:"0.807"}),e.jsx(t.td,{children:"1.056"}),e.jsx(t.td,{children:"3,692"}),e.jsx(t.td,{children:"43.8 km/h"})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:e.jsx(t.strong,{children:"2.4"})}),e.jsx(t.td,{children:e.jsx(t.strong,{children:"0.851"})}),e.jsx(t.td,{children:e.jsx(t.strong,{children:"1.000"})}),e.jsx(t.td,{children:"4,135"}),e.jsx(t.td,{children:"51.5 km/h"})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"5.0"}),e.jsx(t.td,{children:"0.960"}),e.jsx(t.td,{children:"1.000"}),e.jsx(t.td,{children:"6,505"}),e.jsx(t.td,{children:"91.5 km/h"})]})]})]}),`
`,e.jsx(t.p,{children:"At t = 0.0 the engine is at 826 rpm — 6 rpm above its own idle — already passing 57 N·m through the converter at a speed ratio of 0.001. The car has not moved, yet the converter is already doing something a clutch bolted directly to the engine could not: sending torque forward without a mechanical connection stiff enough to stall the engine."}),`
`,e.jsx(t.p,{children:"By 2.4 seconds the turbine has caught up to 85.1% of pump speed — this box's coupling point — and torque ratio has settled at exactly 1.00. Past that instant the stator is freewheeling and the converter is nothing more than a fluid coupling with a few percent slip, which is the entire reason a lockup clutch exists (below)."}),`
