`,e.jsxs(t.li,{children:[e.jsx(t.a,{href:"/blog/what-is-engine-knock",children:"What engine knock is"})," — the derate that ends the gain, and what the knock index measures"]}),`
`,e.jsxs(t.li,{children:[e.jsx(t.a,{href:"/blog/otto-cycle-explained",children:"The Otto cycle explained"})," — the efficiency curve behind the first table, with a live P-V diagram"]}),`
