`,e.jsxs(t.li,{children:[e.jsx(t.a,{href:"/blog/roots-vs-centrifugal-supercharger",children:"Roots vs centrifugal superchargers"})," — the same knock ceiling applied to a belt-driven compressor"]}),`
`,e.jsxs(t.li,{children:[e.jsx(t.a,{href:"/blog/why-f1-engines-rev-to-20000-rpm",children:"Why F1 engines rev to 20,000 rpm"})," — 13.3:1 at 19,250 rpm, and the residence time that makes it possible"]}),`
