`]})]})}function Nt(n={}){const{wrapper:t}=n.components||{};return t?e.jsx(t,{...n,children:e.jsx(J,{...n})}):J(n)}const Dt=Object.freeze(Object.defineProperty({__proto__:null,default:Nt,frontmatter:ve},Symbol.toStringTag,{value:"Module"})),Te={title:"Roots vs Centrifugal Supercharger: Boost Curves Compared",date:"2026-08-23",excerpt:"Two crank-driven blowers, two pressure laws. Measured torque, belt drag and charge heat on one 6.2 V8 — plus the A/B that says which difference matters.",readingMinutes:17,draft:!1,image:"/blog/roots-vs-centrifugal.png",imageAlt:"Line chart comparing delivered pressure ratio against engine speed for a Roots and a centrifugal supercharger, both sized to deliver 1.567 at 5,270 rpm. The Roots line climbs steeply off idle and flattens into a shelf; the centrifugal line stays near atmospheric until 3,000 rpm then climbs past it"};function G(n){const t={a:"a",blockquote:"blockquote",code:"code",em:"em",h2:"h2",h3:"h3",img:"img",li:"li",ol:"ol",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...n.components};return e.jsxs(e.Fragment,{children:[e.jsx(t.p,{children:"Two superchargers can be bolted to the same engine, geared to the same crankshaft, and sized to deliver exactly the same pressure at the same rpm — and still behave nothing alike. One is already three quarters of the way to full boost by 2,000 rpm and runs flat from there. The other gives you almost nothing until the tachometer is past halfway."}),`
`,e.jsx(t.p,{children:"That difference is not tuning. It is which machine you bought, and it shows up in the arithmetic before it shows up on a dyno."}),`
