`]})]})}function zt(n={}){const{wrapper:t}=n.components||{};return t?e.jsx(t,{...n,children:e.jsx(K,{...n})}):K(n)}const Jt=Object.freeze(Object.defineProperty({__proto__:null,default:zt,frontmatter:Ae},Symbol.toStringTag,{value:"Module"})),Ce={title:"Supercharger vs Turbocharger: Which Makes More Power? We Fitted Both to One V8",date:"2026-09-11",updated:"2026-09-29",excerpt:"Supercharger or turbocharger? We fitted a Roots, a centrifugal and a turbo to one 6.2 V8. The turbo wins peak power, the Roots leads below 2,080 rpm.",readingMinutes:22,author:"Engine Simulator Team",draft:!1,image:"/blog/supercharger-vs-turbo-cover.jpg",imageAlt:"A cast-aluminium Roots supercharger and a turbocharger side by side on a scarred steel bench in front of a bare V8 block, under one workshop lamp"};function X(n){const t={a:"a",blockquote:"blockquote",code:"code",em:"em",h2:"h2",h3:"h3",img:"img",li:"li",ol:"ol",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...n.components};return e.jsxs(e.Fragment,{children:[e.jsx(t.p,{children:"Supercharger versus turbocharger: which makes more power? The usual answer is that a turbo makes more power because exhaust energy is free, and a blower makes more torque because it is there from idle. Both halves are half right, and nobody in the thread has bolted all three machines to the same engine, because on a real V8 that is three intake systems, two exhaust systems and a season of weekends."}),`
`,e.jsx(t.p,{children:"In our simulator it is one dropdown and one button. Load the supercharged 6.2 V8 and run the dyno with the Roots blower it ships with: 534.01 hp. Swap the blower for a centrifugal: 558.95. Take the blower off and press FIT TURBOCHARGER: 612.51. Take everything off and the same 6.17 L, 9.5:1 engine makes 338.65 hp on its own. Then hold the engine wide open at 1,000 rpm and read torque instead. The Roots makes 585.2 N·m, the turbo 505.7 and the centrifugal 495.7, so the machine that wins the dyno peak comes third at the bottom of the tachometer."}),`
`,e.jsxs(t.blockquote,{children:[`
`,e.jsx(t.p,{children:e.jsx(t.strong,{children:"Key Takeaways"})}),`
`,e.jsxs(t.ul,{children:[`
`,e.jsxs(t.li,{children:["On one 6.17 L, 9.5:1 V8 on 98 octane, each induction sized to its own knock ceiling with the same intercooler: naturally aspirated ",e.jsx(t.strong,{children:"338.65 hp"}),", Roots ",e.jsx(t.strong,{children:"534.01"}),", centrifugal ",e.jsx(t.strong,{children:"558.95"}),", turbo ",e.jsx(t.strong,{children:"612.51"}),". The turbo wins peak power (",e.jsx(t.strong,{children:"+80.9%"})," over NA) and peak torque (",e.jsx(t.strong,{children:"871.59 N·m"})," against the Roots' 768.88)."]}),`
`,e.jsxs(t.li,{children:["The Roots leads below ",e.jsx(t.strong,{children:"2,080 rpm"}),": 585.2 N·m at 1,000 rpm against the turbo's 505.7 and the centrifugal's 495.7. The turbo passes it at 2,080; the centrifugal passes the Roots at 4,610 and never catches the turbo."]}),`
`,e.jsxs(t.li,{children:["The crank pays for a blower through the belt: ",e.jsx(t.strong,{children:"31.7 kW (42.5 hp)"})," for the Roots and ",e.jsx(t.strong,{children:"41.5 kW (55.7 hp)"})," for the centrifugal at 6,000 rpm. The turbo pays in exhaust backpressure, 2.06 bar at 6,000, and that bill comes to ",e.jsx(t.strong,{children:"9.1 N·m, 5.7 kW"}),"."]}),`
`,e.jsxs(t.li,{children:["Response at a held 2,000 rpm, throttle snapped open: the Roots reaches 90% of its boost in ",e.jsx(t.strong,{children:"0.26 s"}),", the centrifugal in 0.35 s, the turbo in ",e.jsx(t.strong,{children:"1.54 s"}),", six times the Roots."]}),`
`,e.jsx(t.li,{children:'"1.5 bar" is three different curves. Pinned to the same target, the Roots holds 1.39 to 1.50 from 2,000 rpm up, the centrifugal passes 1.5 above its 5,270 rpm anchor, and the turbo creeps to 1.749 at 6,000.'}),`
`]}),`
