`,e.jsxs(t.li,{children:[e.jsx(t.a,{href:"https://www.eaton.com/us/en-us/products/engine-solutions/superchargers/tvs-overview.html",children:"Eaton, TVS supercharger technology overview"}),": positive-displacement rotor geometry (retrieved 2026-09-11)"]}),`
`,e.jsxs(t.li,{children:[e.jsx(t.a,{href:"https://www.procharger.com/supercharger-technology/",children:"ProCharger, supercharger technology"}),": centrifugal pressure as a function of impeller tip speed (retrieved 2026-09-11)"]}),`
`,e.jsxs(t.li,{children:[e.jsx(t.a,{href:"https://www.garrettmotion.com/knowledge-center-category/racing-and-performance/what-is-the-difference-between-a-wastegate-and-a-blow-off-valve/",children:"Garrett Motion, What is the difference between a wastegate and a blow-off valve?"}),": the spring-and-diaphragm wastegate ahead of the turbine (retrieved 2026-09-11)"]}),`
`,e.jsxs(t.li,{children:[e.jsx(t.a,{href:"https://www.garrettmotion.com/knowledge-center-category/oem/what-is-a-turbo-and-how-does-it-work/",children:"Garrett Motion, What Is a Turbo and How Does It Work?"}),": the exhaust-driven turbine and compressor on one shaft (retrieved 2026-09-11)"]}),`
`,e.jsxs(t.li,{children:[e.jsxs(t.a,{href:"https://ntrs.nasa.gov/citations/20090011948",children:["Beede, Kovach and Creagh, ",e.jsx(t.em,{children:"Performance of J-33-A-21 Turbojet-Engine Compressor I"}),", NACA-RM-SE8C15 (1948)"]}),": a centrifugal compressor's efficiency measured across its speed range (retrieved 2026-09-11)"]}),`
`,e.jsxs(t.li,{children:[e.jsxs(t.a,{href:"https://ntrs.nasa.gov/citations/19930091397",children:["Schey and Gove, ",e.jsx(t.em,{children:"The Effect of Supercharger Capacity on Engine and Airplane Performance"}),", NACA-TR-327 (1930)"]}),": a crank-driven Roots blower tested at four drive ratios, a century of the mechanical drive (retrieved 2026-09-11)"]}),`
