`]})]})}function Gt(n={}){const{wrapper:t}=n.components||{};return t?e.jsx(t,{...n,children:e.jsx(X,{...n})}):X(n)}const Kt=Object.freeze(Object.defineProperty({__proto__:null,default:Gt,frontmatter:Ce},Symbol.toStringTag,{value:"Module"})),Se={title:"Two-Stroke vs Four-Stroke Engine: What Actually Differs (Measured)",date:"2026-08-25",updated:"2026-09-13",excerpt:"A two-stroke fires every revolution, so it should make twice the power at equal displacement. It doesn't — measured here at 1.89x to 2.35x, and the reason is not what most explanations say.",readingMinutes:14,author:"Engine Simulator Team",draft:!1,image:"/blog/two-stroke-four-stroke-hero.png",imageAlt:"Two engine cylinder cutaways side by side, split down the centre. On the left, in cyan, a two-stroke with no valves and a port cut into the cylinder wall. On the right, in amber, a four-stroke of the same size with a cylinder head carrying two poppet valves and a camshaft above."};function U(n){const t={a:"a",blockquote:"blockquote",code:"code",em:"em",h2:"h2",h3:"h3",img:"img",li:"li",ol:"ol",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...n.components};return e.jsxs(e.Fragment,{children:[e.jsx(t.p,{children:'A two-stroke engine fires once every crank revolution. A four-stroke fires once every two revolutions — half as often, from an identical cylinder. The textbook shorthand is that a two-stroke should therefore make roughly twice the power. It is close, but never exact, and the gap between "roughly" and "exactly" is where the entire mechanism actually lives.'}),`
`,e.jsx(t.p,{children:'Most explanations stop at "it loses some charge out the exhaust port." That is true, but it is not the whole story, and it is not even the most interesting part of it. This is a controlled measurement — one cylinder, one variable flipped — with the real number the shortfall comes from.'}),`
`,e.jsxs(t.blockquote,{children:[`
`,e.jsx(t.p,{children:e.jsx(t.strong,{children:"Key Takeaways"})}),`
`,e.jsxs(t.ul,{children:[`
`,e.jsxs(t.li,{children:["Flipping one preset from two-stroke to four-stroke, with bore, stroke, compression ratio and everything else held identical, measured a power ratio of ",e.jsx(t.strong,{children:"2.35x on a 249 cc single"}),", ",e.jsx(t.strong,{children:"2.19x on a 748 cc triple"}),", and ",e.jsx(t.strong,{children:"1.89x on a 6,974 cc diesel six"})," — never the naive 2.0x, and never in the same direction of error."]}),`
`,e.jsxs(t.li,{children:["The reason is ",e.jsx(t.strong,{children:"not"})," primarily lost charge. Measured brake mean effective pressure — the actual work done per cycle per unit of swept volume — comes out ",e.jsx(t.strong,{children:"within 0.7%"})," between the two-stroke and four-stroke versions of the 249 cc cylinder. The two-stroke's cylinder is not doing more work per stroke. It is just doing it twice as often."]}),`
`,e.jsxs(t.li,{children:["A two-stroke's real compression only starts once the exhaust port closes, so its ",e.jsx(t.strong,{children:"trapped compression ratio"})," is far below the number on a spec sheet — measured at ",e.jsx(t.strong,{children:"6.97:1"})," on a cylinder whose geometric ratio is quoted as 10.6:1."]}),`
