`]})]})}function on(n={}){const{wrapper:t}=n.components||{};return t?e.jsx(t,{...n,children:e.jsx(te,{...n})}):te(n)}const hn=Object.freeze(Object.defineProperty({__proto__:null,default:on,frontmatter:Ie},Symbol.toStringTag,{value:"Module"})),Me={title:"Why Do Diesel Engines Make So Much Torque? We Took the Turbo Off to Find Out",date:"2026-09-10",excerpt:"Long stroke, high compression, or the turbo? We measured a Cummins 6BT against two gasoline V8s, then removed each lever to see which one torque follows.",readingMinutes:20,author:"Engine Simulator Team",draft:!1,image:"/blog/diesel-torque-cover.jpg",imageAlt:"An inline-six diesel long block on a red engine stand with its head removed and six bores showing, a large cast-iron turbocharger sitting detached on a wooden workbench in the foreground, an aluminium small-block V8 on a second stand behind it, cold window light from the left and a warm work lamp on the right"};function ne(n){const t={a:"a",blockquote:"blockquote",code:"code",em:"em",h2:"h2",h3:"h3",li:"li",ol:"ol",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...n.components};return e.jsxs(e.Fragment,{children:[e.jsx(t.p,{children:"A Cummins 6BT displaces 5.9 litres and, in our simulator, makes 607 N·m at 1,714 rpm. A Ford Modular 4.6 V8 displaces 4.6 litres and makes 395 at 3,918. Ask a truck forum why diesel engines make so much torque and you will have five answers inside a minute: the long stroke, the compression ratio, the turbo, the fuel, the slow burn. Every listicle on the first page of results names the same five and weighs none of them."}),`
`,e.jsx(t.p,{children:"We can weigh them. The 6BT in our roster is calibrated to the real engine's 1998 rating within 1.3%, and its turbo, its stroke and its compression ratio are each one field in a config file. So we took them off one at a time and watched where the torque went."}),`
`,e.jsxs(t.blockquote,{children:[`
`,e.jsx(t.p,{children:e.jsx(t.strong,{children:"Key Takeaways"})}),`
`,e.jsxs(t.ul,{children:[`
`,e.jsxs(t.li,{children:["Per litre, the turbodiesel leads by a margin, not a multiple. In our simulator the 6BT makes ",e.jsx(t.strong,{children:"12.97 bar"})," of BMEP at its torque peak against the LS7's ",e.jsx(t.strong,{children:"11.61"})," and the 4.6's ",e.jsx(t.strong,{children:"10.78"}),": ",e.jsx(t.strong,{children:"+12%"})," and ",e.jsx(t.strong,{children:"+20%"}),"."]}),`
`,e.jsxs(t.li,{children:["Take the turbo off and the diesel falls to ",e.jsx(t.strong,{children:"9.24 bar"})," and ",e.jsx(t.strong,{children:"73.5 N·m per litre"}),", below both gasoline V8s. The turbo is ",e.jsx(t.strong,{children:"29%"})," of its torque, and that is the air side alone."]}),`
`,e.jsxs(t.li,{children:["The diesel's 120 mm stroke, given to the 4.6 at equal displacement, created no torque: ",e.jsx(t.strong,{children:"−3.8%"})," at the peak, and the peak moved ",e.jsx(t.strong,{children:"379 rpm"})," down the tach."]}),`
`,e.jsxs(t.li,{children:["The diesel's 17.5:1 compression, given to the 4.6 with knock switched off, is worth ",e.jsx(t.strong,{children:"+29.5%"}),", about ",e.jsx(t.strong,{children:"3.2% per point"})," compounded. Pump gasoline cannot collect it."]}),`
`,e.jsxs(t.li,{children:["The rev ceiling is a burn fixed in time, not the stroke. Scaled with rpm, the burn costs ",e.jsx(t.strong,{children:"13%"})," of the torque at 3,000 and ",e.jsx(t.strong,{children:"21%"})," at 4,000, while mean piston speed at redline is ",e.jsx(t.strong,{children:"12.0 m/s"})," against the LS7's ",e.jsx(t.strong,{children:"23.7"}),"."]}),`
`]}),`
